create extension if not exists pgcrypto;
create type app_role as enum ('owner','manager','staff','vendor','customer');
create table profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role app_role not null default 'customer', created_at timestamptz default now());
create table stores(id uuid primary key default gen_random_uuid(), name text not null, address jsonb, timezone text default 'America/New_York', created_at timestamptz default now());
create table store_memberships(id uuid primary key default gen_random_uuid(), store_id uuid references stores(id) on delete cascade, user_id uuid references profiles(id) on delete cascade, role app_role not null, unique(store_id,user_id));
create table vendors(id uuid primary key default gen_random_uuid(), store_id uuid references stores(id) on delete cascade, owner_user_id uuid references profiles(id), name text not null, status text default 'active', created_at timestamptz default now());
create table products(id uuid primary key default gen_random_uuid(), store_id uuid references stores(id) on delete cascade, vendor_id uuid references vendors(id), name text not null, description text, category text, status text default 'draft', created_at timestamptz default now());
create table product_variants(id uuid primary key default gen_random_uuid(), product_id uuid references products(id) on delete cascade, sku text unique not null, size text, color text, price numeric(12,2) not null, qty_on_hand integer not null default 0);
create table employees(id uuid primary key default gen_random_uuid(), store_id uuid references stores(id) on delete cascade, user_id uuid references profiles(id), hourly_rate numeric(10,2), status text default 'active');
create table time_entries(id uuid primary key default gen_random_uuid(), employee_id uuid references employees(id) on delete cascade, clock_in timestamptz not null, clock_out timestamptz, break_minutes integer default 0, approved_by uuid references profiles(id));
create table leases(id uuid primary key default gen_random_uuid(), vendor_id uuid references vendors(id) on delete cascade, space_code text, monthly_rent numeric(12,2) not null, deposit numeric(12,2) default 0, start_date date not null, end_date date, status text default 'draft', signed_at timestamptz);
create table rent_payments(id uuid primary key default gen_random_uuid(), lease_id uuid references leases(id) on delete cascade, amount numeric(12,2) not null, method text, paid_at timestamptz default now(), receipt_no text unique);
create table orders(id uuid primary key default gen_random_uuid(), store_id uuid references stores(id) on delete cascade, customer_id uuid references profiles(id), channel text not null, status text not null default 'open', subtotal numeric(12,2) default 0, tax numeric(12,2) default 0, total numeric(12,2) default 0, created_at timestamptz default now());
create table order_items(id uuid primary key default gen_random_uuid(), order_id uuid references orders(id) on delete cascade, variant_id uuid references product_variants(id), vendor_id uuid references vendors(id), qty integer not null, unit_price numeric(12,2) not null);
create table payments(id uuid primary key default gen_random_uuid(), order_id uuid references orders(id) on delete cascade, method text not null, amount numeric(12,2) not null, status text default 'succeeded', provider_ref text, created_at timestamptz default now());
create table measurement_profiles(id uuid primary key default gen_random_uuid(), customer_id uuid references profiles(id) on delete cascade, label text not null, units text default 'in', measurements jsonb not null default '{}'::jsonb, created_at timestamptz default now());
create table audit_log(id bigint generated always as identity primary key, actor_user_id uuid, store_id uuid, action text not null, entity_type text not null, entity_id text, before_data jsonb, after_data jsonb, created_at timestamptz default now());
